# Helper to locate the first line after a YAML front‑matter block.
get_frontmatter_start <- function(lines) {
  # lines: character vector (e.g. skill_content)
  if (length(lines) > 0 && lines[1] == "---") {
    yaml_end <- which(lines == "---")
    if (length(yaml_end) >= 2) {
      return(yaml_end[2] + 1)
    }
  }
  return(1)
}
